// swift-tools-version:6.0
import PackageDescription
import Foundation

// MARK: - Plozz modular package
//
// Plozz is split into small, single-responsibility modules so that:
//  * pure logic (models, networking, discovery, session) is unit-testable in
//    isolation, without a running tvOS UI;
//  * a second provider (Plex, Phase 2) can be dropped in behind `MediaProvider`
//    without touching feature code;
//  * build times stay low and ownership boundaries stay clear.
//
// The platform application targets live in `App/` and are generated by
// XcodeGen (see `project.yml`); they link their platform-specific shells below.
let package = Package(
    name: "Plozz",
    // Required before any target may own localized resources, and — more
    // importantly here — it is what makes the Swift compiler's string extraction
    // emit per-module tables for this package's targets. Without it,
    // `xcodebuild -exportLocalizations` silently produces an EMPTY catalog even
    // when `.stringsdata` files are being written. See docs/localization.md.
    defaultLocalization: "en",
    platforms: [
        .iOS(.v18),
        .tvOS(.v18)
    ],
    products: [
        .library(name: "CoreModels", targets: ["CoreModels"]),
        .library(name: "CoreNetworking", targets: ["CoreNetworking"]),
        .library(name: "CoreUI", targets: ["CoreUI"]),
        .library(name: "MetadataKit", targets: ["MetadataKit"]),
        .library(name: "FeatureDiscoveryCore", targets: ["FeatureDiscoveryCore"]),
        .library(name: "FeatureDiscovery", targets: ["FeatureDiscovery"]),
        .library(name: "ProviderJellyfin", targets: ["ProviderJellyfin"]),
        .library(name: "ProviderPlex", targets: ["ProviderPlex"]),
        .library(name: "ProviderShare", targets: ["ProviderShare"]),
        .library(name: "ProviderTrailers", targets: ["ProviderTrailers"]),
        .library(name: "RatingsService", targets: ["RatingsService"]),
        .library(name: "TraktService", targets: ["TraktService"]),
        .library(name: "SeerService", targets: ["SeerService"]),
        .library(name: "SimklService", targets: ["SimklService"]),        .library(name: "AniListService", targets: ["AniListService"]),
        .library(name: "MALService", targets: ["MALService"]),
        .library(name: "LastFmService", targets: ["LastFmService"]),
        .library(name: "CoreSecureStore", targets: ["CoreSecureStore"]),
        .library(name: "FeatureAuthCore", targets: ["FeatureAuthCore"]),
        .library(name: "FeatureAuth", targets: ["FeatureAuth"]),
        .library(name: "FeatureHomeCore", targets: ["FeatureHomeCore"]),
        .library(name: "FeatureHome", targets: ["FeatureHome"]),
        .library(name: "FeatureSearchCore", targets: ["FeatureSearchCore"]),
        .library(name: "FeaturePlayback", targets: ["FeaturePlayback"]),
        .library(name: "FeatureSearch", targets: ["FeatureSearch"]),
        .library(name: "FeatureSettings", targets: ["FeatureSettings"]),
        .library(name: "FeatureProfiles", targets: ["FeatureProfiles"]),
        .library(name: "FeatureWatchlistCore", targets: ["FeatureWatchlistCore"]),
        .library(name: "FeatureSyncSetup", targets: ["FeatureSyncSetup"]),
        .library(name: "FeatureSyncCloud", targets: ["FeatureSyncCloud"]),
        .library(name: "FeatureMusic", targets: ["FeatureMusic"]),
        .library(name: "TopShelfKit", targets: ["TopShelfKit"]),
        .library(name: "CrashReporting", targets: ["CrashReporting"]),
        .library(name: "MediaDownloads", targets: ["MediaDownloads"]),
        .library(name: "MediaTransportCore", targets: ["MediaTransportCore"]),
        .library(name: "MediaTransportHTTP", targets: ["MediaTransportHTTP"]),
        .library(name: "MediaTransportSMB", targets: ["MediaTransportSMB"]),
        .library(name: "MediaTransportWebDAV", targets: ["MediaTransportWebDAV"]),
        .library(name: "MediaTransportSFTP", targets: ["MediaTransportSFTP"]),
        .library(name: "TransportNFS", targets: ["TransportNFS"]),
        .library(name: "MediaTransportNFS", targets: ["MediaTransportNFS"]),
        .library(name: "AppRuntime", targets: ["AppRuntime"]),
        .library(name: "AppShell", targets: ["AppShell"]),
        .library(name: "AppShelliOS", targets: ["AppShelliOS"])
    ],
    dependencies: [
        // Pure-Swift, dependency-free YouTube stream extractor. Backs online
        // trailer playback: TMDb hands us a YouTube video id, YouTubeKit resolves
        // a natively-playable progressive stream URL we feed straight to AVPlayer
        // (the same approach Infuse uses). It includes an optional remote fallback
        // so extraction keeps working when YouTube changes its internal API.
        .package(url: "https://github.com/alexeichhorn/YouTubeKit.git", from: "0.4.8"),

        // AetherEngine — production media player engine for Apple platforms.
        // FFmpeg demuxes, VideoToolbox decodes, AVPlayer handles Dolby Atmos.
        // Powers the native HLS-fMP4 remux path for MKV → DoVi + Atmos + seek.
        // See AGENTS.local.md › "Playback engine (AetherEngine / Plozzigen)".
        //
        // Pinned to the UPSTREAM release tag 6.26.0 -> 73354ec8c6d20ca954b1874254b69fa19e2ffce5.
        //
        // Plozz no longer carries an AetherEngine fork. Everything the old
        // `plozz-pin-*` stack existed for is upstream as of 5.23.2:
        //   - E-AC-3 JOC / Atmos detection probe            (#214, upstream 5.21.0+)
        //   - opt-in AVAudioSession release on teardown     (#215, upstream 5.23.0+)
        //   - slow-source VOD seek recovery, no clock revert (#216, upstream 5.23.1+)
        // each with upstream's own follow-up hardening on top (JOC scan correctness,
        // engine-level + off-main-actor session release, and three seek-loop edges).
        //
        // 5.23.5 also carries the fix for AetherEngine#222, which we reported: an
        // E-AC-3 title whose first segment contains no audio wedged the muxer at
        // 00:00, because the cut path forced a moov with no parsed frame to build
        // `dec3` from. Every Jellyfin direct-play of such a file fell back to a full
        // server transcode. The fix primes the muxer with a real audio frame, so the
        // E-AC-3 stream-copy (and its Atmos signaling) is preserved rather than
        // bridged away.
        //
        // 5.23.7 is the reason this bump is not optional: 5.23.4 (which 5.23.5
        // carries) anchored the reported buffer frontier at the consumer's fetch
        // target, and that anchor only holds inside an uninterrupted fetch
        // sequence. A seek removes the bound, so for one tick the walk measured a
        // freshly produced band against the position the seek jumped away from and
        // reported a lead the size of the seek distance (a field report saw ~35 min
        // claimed over a playhead with nothing resident ahead of it). 5.23.7 bounds
        // the anchor to the fetch sequence and falls back to the playhead outside
        // it. Never take 5.23.4 without 5.23.7.
        // Tracking upstream releases directly is now strictly better than the fork.
        //
        // Still pinned by exact SHA rather than a version range: the engine is the
        // playback path, so a bump is a deliberate, device-tested change.
        //
        // Now 6.0.2 (was 5.23.8). Two things about this bump are worth knowing
        // before anyone moves it again:
        //
        //   * Take 6.0.1 or later, never 6.0.0. LibDovi shipped its visionOS
        //     slices and a tvOS floor correction together as 1.1.0; a raised
        //     floor is breaking, so SwiftPM resolved that minor into every
        //     consumer pinning `from: "1.0.x"` and then failed on the mismatch
        //     instead of backing off. LibDovi 1.1.0 was withdrawn and republished
        //     as 2.0.0, which 6.0.1+ pins. 6.0.0 still points at the withdrawn
        //     tag and does not resolve at all.
        //   * 6.0.0 raised the engine's tvOS floor to 17.0 — a correction, since
        //     LibDovi's tvOS slices were always built `-mtvos-version-min=17.0`.
        //     Plozz targets tvOS 18, so this costs us nothing. It is the only
        //     breaking change across the 84 releases in this range; no public
        //     symbol was removed or renamed.
        //
        // Pinned to the 6.26.0 RELEASE rather than upstream HEAD. Same reasoning as
        // the exact-SHA pin: the playback path takes documented, released changes
        // only. The SHA is the COMMIT the 6.26.0 tag points at, not the annotated
        // tag object's own id — a `revision:` pin wants the commit.
        //
        // Moved up from 6.6.0. Nine minor releases plus patches, every one of them
        // documented drop-in with no consumer source change, no symbol removed or
        // renamed. The ones that matter to shapes Plozz actually serves:
        //   - 6.15.2 the live `AVIOReader` stopped cycling its own healthy
        //     connections. The 16 MB high-water end had no live branch, so it was
        //     the only thing terminating a healthy live connection: each end
        //     dropped everything broadcast during the ~8 MB drain and the demuxer
        //     rejoined on a corrupt TS packet.
        //   - 6.15.1 a `nativeRemoteHLS` bypass that could neither play nor fail
        //     (an origin answering everything while AVFoundation builds no track)
        //     now does one of the two instead of sitting in `.loading` forever.
        //   - 6.14.0 `LoadOptions.externalSubtitles` was silently dropped on a
        //     remote-HLS source — empty `subtitleTracks`, no error, indistinguishable
        //     from a source with no subtitles.
        //   - 6.12.0 a source connection that dies silently is now noticed on
        //     wall-clock time rather than only once a consumer drains the window.
        //   - 6.11.0 an origin refusing every refill no longer spirals into ~15
        //     reconnects a second.
        //   - 6.13.0 `hasFirstFrameReadyForDisplay`, the edge a black cover should
        //     come off on. `isSessionReady` is `readyToPlay`, which AVFoundation
        //     reaches before the layer holds a picture and which stays true across
        //     a seek — so it lifts a cover onto black. Plozz approximates this today
        //     with `awaitingFirstFrame`; worth revisiting that against this signal.
        //
        // Moved up from 6.15.2 to 6.26.0. Eleven minor releases plus patches, all
        // documented drop-in with no consumer source change, no public symbol
        // removed or renamed. Highlights across the span:
        //   - 6.26.0 the error string is treated as a payload, not a lookup key.
        //   - 6.25.x source measurement over trust; timeshift archives on their own
        //     axis; SEI preservation at the record door.
        //   - 6.24.0 live playlists reach the header-carrying path.
        //   - 6.21.0–6.23.x live HLS subtitle renditions, system caption requests
        //     reaching the host, determinate startup-progress checkpoints.
        //   - 6.20.x segment grid aligned to the source's own keyframes.
        //   - 6.16.0–6.19.x AirPlay/first-frame settle-gate correctness, codec
        //     routing defaults, and pgssub cue timing.
        //
        // SMB enters AetherEngine only through Plozz's protocol-neutral custom-source
        // bridge; the engine's legacy SMB URL product is not linked.
        .package(url: "https://github.com/superuser404notfound/AetherEngine", revision: "73354ec8c6d20ca954b1874254b69fa19e2ffce5"),
        // NOTE: FFmpegBuild (FFmpeg n8.1.x decode-only) and LibDovi (Dolby Vision
        // RPU parser) are pulled in TRANSITIVELY by AetherEngine — its own manifest
        // declares and consumes them. Plozz used to declare them directly only for
        // the retired hybrid-engine target; no Plozz target references
        // their products, so the direct declarations were removed (SwiftPM flagged
        // them as unused). AetherEngine owns their version alignment.

        // Sentry (getsentry/sentry-cocoa) — powers the OPT-IN, off-by-default
        // crash reporter (Settings ▸ Help & Diagnostics ▸ Share Crash Reports).
        // Prebuilt binary xcframework (no build-time compilation of the SDK).
        // Nothing is sent unless the user opts in AND a DSN was baked into the
        // build; see the `CrashReporting` target for the privacy-hardened config.
        .package(url: "https://github.com/getsentry/sentry-cocoa", from: "9.19.0"),

        // SMBClient — pure-Swift, MIT SMB client over NWConnection. Declared here
        // for the isolated **MediaTransportSMB** adapter and ProviderShare's
        // pre-save discovery/share enumeration. Browsing and scanning consume the
        // protocol-neutral MediaTransportCore contracts. AetherEngine already pulls
        // SMBClient transitively and owns the playback byte-reads (SMBConnection);
        // SwiftPM unifies both onto one version.
        //
        // Pinned to thatcube/SMBClient@smb3, our fork that adds SMB 3.x + 3.1.1
        // GCM encryption and Session.isGuestSession (see the guest/credential
        // handling in ProviderShare/SMBDiscovery). This root-level reference
        // overrides the same-identity ("smbclient") reference AetherEngine pulls
        // transitively, so BOTH browse and playback use the SMB3 fork. Proposed
        // upstream as kishikawakatsumi/SMBClient#234; switch back to
        //   .package(url: "https://github.com/kishikawakatsumi/SMBClient", from: "0.3.1"),
        // once that lands.
        .package(url: "https://github.com/thatcube/SMBClient.git", revision: "d8baadc1a4f1287ebf1e8b4702ca38bd6e237fef"),

        // swift-nio-ssh — Apple's pure-Swift SSH protocol implementation
        // (Apache-2.0), used ONLY by the isolated **MediaTransportSFTP** adapter.
        // It declares tvOS support directly and rides Apple's own swift-nio +
        // swift-crypto (no third-party fork), so the security-critical SSH/host-key
        // layer stays on a maintained upstream. It provides the SSH transport only
        // — MediaTransportSFTP layers a thin, read-only SFTP v3 subsystem client on
        // top (INIT/REALPATH/OPENDIR/OPEN/FSTAT/READ/CLOSE) behind the neutral
        // MediaTransportCore contracts, mirroring MediaTransportSMB's shape. This is
        // the deliberate alternative to Citadel, whose main rides a stale personal
        // fork-of-a-fork of swift-nio-ssh for that same credential/host-key path.
        .package(url: "https://github.com/apple/swift-nio-ssh.git", from: "0.11.0"),

        // swift-nio — declared directly so MediaTransportSFTP can import the NIO
        // core products (NIOCore/NIOPosix/NIOFoundationCompat/NIOConcurrencyHelpers)
        // it needs to drive swift-nio-ssh's channels. Already resolved transitively
        // via swift-nio-ssh; SwiftPM unifies the version.
        .package(url: "https://github.com/apple/swift-nio.git", from: "2.81.0"),

        // swift-crypto — declared directly for MediaTransportSFTP's SSH host-key
        // SHA-256 fingerprinting (and, in tests, ed25519 key material for the
        // pin). Apple-maintained, tvOS-supported, already resolved transitively
        // via swift-nio-ssh; SwiftPM unifies the version.
        .package(url: "https://github.com/apple/swift-crypto.git", "3.0.0" ..< "5.0.0"),
    ],
    targets: [
        // MARK: Core
        .target(
            name: "CoreModels",
            swiftSettings: [
                .define("PLOZZ_DIAGNOSTICS", .when(configuration: .debug))
            ]
        ),
        .target(
            name: "CoreNetworking",
            dependencies: ["CoreModels"]
        ),

        // MARK: Shared UI (design system + reusable tvOS components)
        .target(
            name: "CoreUI",
            dependencies: ["CoreModels", "MetadataKit"],
            resources: [.process("Resources")]
        ),

        // MARK: Scalable external metadata/artwork (content-type-routed providers)
        //
        // Foundation-only so it stays unit-testable off-device. Houses the keyless,
        // per-IP artwork providers (AniList, Kitsu, TVmaze, Deezer, MusicBrainz),
        // the optional proxy/token-gated TMDb provider, the content-type classifier
        // + ArtworkRouter that picks the right provider chain, and a persistent
        // resolved-URL disk cache. This is the engine behind goals 1–5 scaling to
        // a large user base without a "bring your own API key" design.
        .target(
            name: "MetadataKit",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),

        // MARK: Providers
        .target(
            name: "ProviderJellyfin",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),
        .target(
            name: "ProviderPlex",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),
        // Second-class local media-share backend (SMB today). Scans a share into
        // a synthesised library and conforms to `MediaProvider` so the rest of the
        // app treats it like Plex/Jellyfin. Runtime browsing/scanning use injected
        // MediaTransportCore sessions; SMBClient remains here only for setup-time
        // SMB discovery/share enumeration. Playback still flows through
        // EnginePlozzigen's existing SMB path. See docs/media-share-proposal.md.
        .target(
            name: "ProviderShare",
            dependencies: [
                "CoreModels",
                "CoreNetworking",
                "MediaTransportCore",
                "MetadataKit",
                .product(name: "SMBClient", package: "SMBClient"),
            ]
        ),
        // Synthetic provider for online (TMDb → YouTube) trailers. Conforms to
        // `MediaProvider` so a trailer can be played by the existing player; only
        // `playbackInfo(for:)` does real work (YouTubeKit stream extraction), the
        // rest are inert stubs. Kept in its own leaf module so YouTubeKit stays
        // out of every other target's link graph.
        .target(
            name: "ProviderTrailers",
            dependencies: [
                "CoreModels",
                .product(name: "YouTubeKit", package: "YouTubeKit")
            ]
        ),
        .target(
            name: "RatingsService",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),
        .target(
            name: "TraktService",
            dependencies: ["CoreModels", "CoreNetworking", "CoreSecureStore"]
        ),
        .target(
            name: "SeerService",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),
        .target(
            name: "SimklService",
            dependencies: ["CoreModels", "CoreNetworking", "CoreSecureStore"]
        ),
        .target(
            name: "AniListService",
            dependencies: ["CoreModels", "CoreNetworking", "CoreSecureStore"]
        ),
        .target(
            name: "MALService",
            dependencies: ["CoreModels", "CoreNetworking", "CoreSecureStore"]
        ),
        .target(
            name: "LastFmService",
            dependencies: ["CoreModels", "CoreNetworking", "CoreSecureStore"]
        ),

        // MARK: Features
        .target(
            name: "FeatureDiscoveryCore",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),
        .target(
            name: "FeatureDiscovery",
            dependencies: ["CoreModels", "CoreUI", "FeatureDiscoveryCore"]
        ),
        .target(
            name: "CoreSecureStore",
            dependencies: ["CoreModels"]
        ),
        .target(
            name: "FeatureAuthCore",
            dependencies: ["CoreModels", "CoreNetworking", "CoreSecureStore", "ProviderJellyfin", "ProviderPlex"]
        ),
        .target(
            name: "FeatureAuth",
            dependencies: ["CoreModels", "CoreUI", "FeatureAuthCore", "ProviderPlex"]
        ),
        .target(
            name: "FeatureHomeCore",
            dependencies: [
                "CoreModels",
                "CoreNetworking",
                // For `PersonDetailViewModel`, which lives here rather than in
                // FeatureHome so BOTH shells can build it: FeatureHome carries
                // unguarded tvOS-only API and is never compiled for iOS.
                "CoreUI",
                "MetadataKit",
                "RatingsService",
                "ProviderTrailers"
            ]
        ),
        .target(
            name: "HeroUI",
            dependencies: ["CoreModels", "CoreUI", "FeatureHomeCore"]
        ),
        .target(
            name: "FeatureHome",
            dependencies: ["CoreModels", "CoreNetworking", "CoreUI", "FeatureHomeCore", "HeroUI", "MetadataKit", "TopShelfKit", "RatingsService", "ProviderTrailers"]
        ),
        .target(
            name: "FeaturePlayback",
            dependencies: ["CoreModels", "CoreNetworking", "CoreUI", "TraktService", "MetadataKit"],
            linkerSettings: [
                // Force-link AVKit on tvOS so its `UIWindow (AVAdditions)`
                // category (which adds `avDisplayManager`, used to drive the
                // Dolby Vision / HDR display-mode switch) is registered at
                // runtime. Swift's autolink hint for a category-only reference
                // gets dropped through the SPM static-lib → app link, leaving the
                // selector unrecognized (instant crash) unless linked explicitly.
                .linkedFramework("AVKit", .when(platforms: [.tvOS]))
            ]
        ),
        .target(
            name: "FeatureSearchCore",
            dependencies: ["CoreModels"]
        ),
        .target(
            name: "FeatureSearch",
            dependencies: ["CoreModels", "CoreUI", "FeatureSearchCore"]
        ),
        .target(
            name: "FeatureSettings",
            dependencies: ["CoreModels", "CoreUI", "CoreNetworking", "CrashReporting", "FeatureProfiles", "TraktService", "SeerService", "SimklService", "AniListService", "MALService", "LastFmService"]
        ),
        .target(
            name: "FeatureProfiles",
            dependencies: ["CoreModels", "CoreUI"]
        ),
        .target(
            name: "FeatureWatchlistCore",
            dependencies: ["CoreModels"]
        ),

        // MARK: Sync & Setup (cross-device onboarding — feature-flagged, v1)
        //
        // Non-secret config sync + device pairing crypto. Depends only on
        // CoreModels; uses CryptoKit for the pairing seal (kept out of the
        // Foundation-only CoreModels). v1 carries NON-SECRET config only.
        .target(
            name: "FeatureSyncSetup",
            dependencies: ["CoreModels"]
        ),

        // Non-secret config auto-sync over CloudKit (CKSyncEngine, private DB).
        // Isolated here because it imports CloudKit; the pure snapshot<->records
        // core lives in CoreModels. Propagates the shared household setup
        // (descriptors, profiles, per-profile settings + membership) across one
        // Apple ID's devices. NEVER carries tokens/passwords (that's pairing).
        .target(
            name: "FeatureSyncCloud",
            dependencies: ["CoreModels", "CoreNetworking"]
        ),

        // MARK: Music (browse + audio playback engine)
        //
        // Self-contained music experience: aggregator/view models, the conditional
        // Music tab UI, and the app-scoped `AudioPlaybackController` (AVQueuePlayer
        // + background audio + Now Playing). Depends only on CoreModels/CoreUI so
        // it stays decoupled from the video feature modules.
        .target(
            name: "FeatureMusic",
            dependencies: ["CoreModels", "CoreUI", "MetadataKit", "CoreNetworking"]
        ),

        // MARK: Top Shelf (shared with the tvOS Top Shelf extension)
        //
        // `TopShelfSnapshot` + `TopShelfStore` are Foundation-only and are also
        // compiled directly into the Top Shelf extension by source path (see
        // project.yml). `TopShelfPublisher` imports CoreModels and is therefore
        // app-only — the extension never compiles it.
        .target(
            name: "TopShelfKit",
            dependencies: ["CoreModels"]
        ),

        // MARK: Crash reporting (opt-in, off by default)
        //
        // Wraps Sentry behind a small `CrashReporter` protocol so the rest of the
        // app never imports Sentry directly and builds without a DSN are a true
        // no-op. Reports are only ever sent when the user has opted in (Settings ▸
        // Help & Diagnostics) AND the build shipped with a `PLOZZ_SENTRY_DSN`.
        // The Sentry config here is privacy-hardened: crash + hang captures only,
        // all automatic UI/network telemetry disabled, and a hard scrub of PII in
        // `beforeSend`/`beforeBreadcrumb`. Depends only on Sentry + Foundation.
        .target(
            name: "CrashReporting",
            dependencies: [
                .product(name: "Sentry", package: "sentry-cocoa"),
            ]
        ),

        // MARK: Protocol-neutral media transport
        .target(
            name: "MediaTransportCore",
            dependencies: ["CoreModels"],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: Offline downloads (headless, shared, platform-neutral)
        //
        // The offline-download FOUNDATION: a durable, resumable, transport-agnostic
        // download registry + queue + policy that both future iOS/iPadOS apps and
        // the tvOS app inherit. Depends only on CoreModels + the protocol-neutral
        // MediaTransportCore (the cursor byte API it downloads through). No UI /
        // Feature / provider modules — arch-guard keeps it a clean lower layer.
        .target(
            name: "MediaDownloads",
            dependencies: ["CoreModels", "MediaTransportCore"]
        ),

        // MARK: WebDAV/HTTP transport
        //
        // Foundation-only WebDAV/plain-HTTP adapter primitives built on the
        // protocol-neutral MediaTransportCore: origin/redirect discipline,
        // credential preflight + password/Bearer auth policy, exact-leaf TLS
        // pinning, per-(account, credential revision, origin, trust
        // revision, role) ephemeral session isolation, bounded PROPFIND
        // parsing, and validated ranged reads. See
        // `Sources/MediaTransportHTTP/README.md` for the adapter's scope.
        //
        // NOT consumed by AppShell/the App target — this is a standalone,
        // independently-testable module, not shipping app behavior yet.
        // Strict concurrency is opted into explicitly for this target only
        // (the package as a whole stays pinned to Swift 5 language mode; see
        // `swiftLanguageModes` below) so this new surface is held to a
        // stricter bar from day one.
        .target(
            name: "MediaTransportHTTP",
            dependencies: ["CoreModels", "MediaTransportCore"],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: SMB transport
        .target(
            name: "MediaTransportSMB",
            dependencies: [
                "CoreModels",
                "MediaTransportCore",
                .product(name: "SMBClient", package: "SMBClient"),
            ],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: WebDAV transport
        //
        // Composes the MediaTransportHTTP primitives (OPTIONS/PROPFIND/range
        // reads, origin/redirect/trust discipline) into a MediaTransportCore
        // adapter, mirroring MediaTransportSMB's shape. No SMBClient/URLSession
        // logic of its own — it only wires the HTTP primitives to the
        // protocol-neutral filesystem/byte-source contracts.
        .target(
            name: "MediaTransportWebDAV",
            dependencies: [
                "CoreModels",
                "MediaTransportCore",
                "MediaTransportHTTP",
            ],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: SFTP transport
        //
        // Layers a thin, read-only SFTP v3 subsystem client on top of Apple's
        // swift-nio-ssh (SSH transport only) and composes it into a
        // MediaTransportCore adapter, mirroring MediaTransportSMB's shape (a
        // stub-testable backend seam, cursor-safe random-access byte source). No
        // SSH/crypto logic of its own — swift-nio-ssh owns key exchange, ciphers,
        // and host-key verification; this module only frames the SFTP messages we
        // need and wires them to the protocol-neutral filesystem/byte-source
        // contracts.
        .target(
            name: "MediaTransportSFTP",
            dependencies: [
                "CoreModels",
                "MediaTransportCore",
                .product(name: "NIOSSH", package: "swift-nio-ssh"),
                .product(name: "NIOCore", package: "swift-nio"),
                .product(name: "NIOPosix", package: "swift-nio"),
                .product(name: "NIOConcurrencyHelpers", package: "swift-nio"),
                .product(name: "NIOFoundationCompat", package: "swift-nio"),
                .product(name: "Crypto", package: "swift-crypto"),
            ],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: NFS transport
        //
        // `TransportNFS` is a self-contained, dependency-free pure-Swift NFSv3
        // client (XDR + ONC-RPC + portmap + MOUNT + read-only NFSv3 procedures)
        // over NWConnection — the NFS analogue of `SMBClient`, but written
        // in-house because no shippable Swift NFS library exists (libnfs is LGPL,
        // a compliance risk for a closed-source App Store app). Foundation +
        // Network only; no CoreModels/MediaTransportCore dependency so the whole
        // protocol layer is unit-testable in isolation.
        .target(
            name: "TransportNFS",
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: MediaTransportNFS adapter
        //
        // Composes the TransportNFS client into a MediaTransportCore adapter,
        // mirroring MediaTransportSMB/MediaTransportWebDAV exactly. The NFS
        // backend sits behind a protocol seam so the adapter/session/filesystem/
        // byte-source can be proven hermetically with a stubbed backend.
        .target(
            name: "MediaTransportNFS",
            dependencies: [
                "CoreModels",
                "MediaTransportCore",
                "TransportNFS",
            ],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: FTP/FTPS transport
        //
        // A minimal FTP protocol engine over Network.framework (NWConnection),
        // composed into the protocol-neutral MediaTransportCore adapter shape —
        // mirroring MediaTransportSMB/WebDAV. Supports plain FTP + implicit FTPS
        // (TLS from connect); explicit FTPS (AUTH TLS/StartTLS) is unavailable on
        // tvOS (Network.framework has no StartTLS) and is rejected at connect.
        // Random-access playback reads use REST (restart offset) + RETR.
        .target(
            name: "MediaTransportFTP",
            dependencies: [
                "CoreModels",
                "MediaTransportCore",
            ],
            swiftSettings: [.unsafeFlags(["-strict-concurrency=complete"])]
        ),

        // MARK: AetherEngine integration (native HLS-fMP4 remux engine)
        //
        // Wraps AetherEngine (the upstream media-player library) behind Plozz's
        // `VideoEngine` protocol. AetherEngine handles: FFmpeg demux → on-device
        // copy-remux → localhost HLS-fMP4 → AVPlayer, with bounded segment cache,
        // backpressure, producer-restart seek, Dolby Vision signaling, and Atmos
        // passthrough. This module is the integration adapter — all Plozz-specific
        // orchestration (server progress, subtitles, routing) stays in
        // FeaturePlayback / PlayerViewModel.
        .target(
            name: "EnginePlozzigen",
            dependencies: [
                "CoreModels",
                "MediaTransportCore",
                "FeaturePlayback",
                .product(name: "AetherEngine", package: "AetherEngine"),
            ]
        ),

        .target(
